"use client";

/* ─────────────────────────────────────────────────────────
 * RANGE RULER: dual needles on a graduated thin line ruler
 *
 *   ruler      an axis with 1px SVG tick marks; major ticks
 *              mark intervals, minor ticks subdivide steps
 *   needles    two tactile thin line sliders with 1px indicators;
 *              needles glide with zero edge-jumping or layout thrash
 *   repulsion  drag the lower needle into the upper one and it
 *              pushes the upper needle forward instead of
 *              clipping; drag backwards and it pushes down
 *   badges     floating metric pills roll with NumberRoll;
 *              when needles get within 48px, badges merge into
 *              a single span readout
 *   mobile     expanded touch targets and track-wide gesture
 *              capture allow effortless finger manipulation
 *
 * Both needles are accessible sliders with full arrow, Home,
 * End, and Page keys.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { NumberRoll } from "./number-roll";
import {
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { snapRulerValue, useRangeRuler } from "./use-range-ruler";

export type RangeValue = [number, number];

export interface RangeRulerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  label?: string;
  value?: RangeValue;
  defaultValue?: RangeValue;
  min?: number;
  max?: number;
  step?: number;
  minDistance?: number;
  unit?: string;
  disabled?: boolean;
  onValueChange?: (value: RangeValue) => void;
  onValueCommit?: (value: RangeValue) => void;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
}

export function RangeRuler({
  label,
  value,
  defaultValue = [20, 80],
  min = 0,
  max = 100,
  step = 1,
  minDistance = 0,
  unit = "",
  disabled = false,
  onValueChange,
  onValueCommit,
  format,
  locales,
  className = "",
  ...props
}: RangeRulerProps) {
  const reduced = useInteractionReducedMotion();
  const lower = Number.isFinite(min) ? min : 0;
  const upper = Number.isFinite(max) && max > lower ? max : lower + 100;
  const increment = Number.isFinite(step) && step > 0 ? step : 1;

  const [own, setOwn] = React.useState<RangeValue>(defaultValue);
  const currentVal = value ?? own;

  const safeVal: RangeValue = React.useMemo(() => {
    const l = snapRulerValue(
      currentVal[0],
      lower,
      upper - minDistance,
      increment,
    );
    const u = snapRulerValue(currentVal[1], l + minDistance, upper, increment);
    return [l, u];
  }, [currentVal, lower, upper, minDistance, increment]);

  const decimals = Math.min(
    4,
    Math.max(0, (String(increment).split(".")[1] ?? "").length),
  );

  const formatter = React.useMemo(
    () => (format || locales ? new Intl.NumberFormat(locales, format) : null),
    [locales, format],
  );

  const formatNumber = React.useCallback(
    (n: number) => {
      const formatted = formatter ? formatter.format(n) : n.toFixed(decimals);
      return unit ? `${formatted} ${unit}` : formatted;
    },
    [decimals, unit, formatter],
  );

  const formatAria = React.useCallback(
    (n: number) => {
      const formatted = formatter ? formatter.format(n) : n.toFixed(decimals);
      return `${formatted}${unit ? ` ${unit}` : ""}`;
    },
    [decimals, unit, formatter],
  );

  const handleChange = React.useCallback(
    (next: RangeValue) => onValueChange?.(next),
    [onValueChange],
  );

  const handleCommit = React.useCallback(
    (next: RangeValue) => {
      if (value === undefined) setOwn(next);
      onValueCommit?.(next);
    },
    [value, onValueCommit],
  );

  const ruler = useRangeRuler({
    value: safeVal,
    min: lower,
    max: upper,
    step: increment,
    minDistance,
    disabled,
    reduced,
    onChange: handleChange,
    onCommit: handleCommit,
    format: formatAria,
    formatNumber,
  });

  const rangeSpan = Math.max(0.00001, upper - lower);
  const tickCount = Math.min(
    81,
    Math.max(11, Math.round(rangeSpan / increment) + 1),
  );
  const majorInterval = Math.max(1, Math.round(tickCount / 8));

  const ticks = React.useMemo(() => {
    return Array.from({ length: tickCount }, (_, i) => {
      const fraction = i / (tickCount - 1);
      const isMajor = i % majorInterval === 0 || i === tickCount - 1;
      return { fraction, isMajor, key: i };
    });
  }, [tickCount, majorInterval]);

  const lowerHint = React.useId();
  const upperHint = React.useId();

  const lowerPercent = Math.max(
    0,
    Math.min(100, ((safeVal[0] - lower) / rangeSpan) * 100),
  );
  const upperPercent = Math.max(
    0,
    Math.min(100, ((safeVal[1] - lower) / rangeSpan) * 100),
  );

  return (
    <div
      {...props}
      role="group"
      aria-label={label ?? "Range selector"}
      className={`relative flex w-full max-w-xl select-none flex-col text-foreground ${className}`}
    >
      {label && (
        <div className="mb-2 flex items-center justify-between text-[12px] font-medium text-muted-foreground">
          <span>{label}</span>
          <span className="font-mono text-[11px] tabular-nums text-muted-foreground/80">
            {formatNumber(safeVal[0])} — {formatNumber(safeVal[1])}
          </span>
        </div>
      )}

      {/* Floating Readout Badges (No heavy shadows, pure thin line borders) */}
      <div className="relative mb-3 h-7 w-full">
        {ruler.isMerged ? (
          <div className="absolute inset-x-0 flex items-center justify-center">
            <div className="inline-flex items-center gap-1 rounded-full border border-border bg-surface px-2.5 py-0.5 text-[11px] font-medium tabular-nums">
              <span
                ref={(el) => ruler.attachMergedReadout(el)}
                style={{ display: ruler.activeThumb ? "inline" : "none" }}
              >
                {formatNumber(safeVal[0])} – {formatNumber(safeVal[1])}
              </span>
              <span style={{ display: ruler.activeThumb ? "none" : "inline" }}>
                <NumberRoll value={safeVal[0]} duration={380} />
                <span className="mx-1 text-muted-foreground">–</span>
                <NumberRoll value={safeVal[1]} duration={380} />
                {unit && (
                  <span className="ml-1 text-muted-foreground">{unit}</span>
                )}
              </span>
            </div>
          </div>
        ) : (
          <div className="relative size-full">
            <div
              className="absolute -top-0.5 transition-[opacity,left] duration-200"
              style={{
                left: `${lowerPercent}%`,
                transform: "translate(-50%, 0)",
              }}
            >
              <div className="inline-flex items-center rounded-full border border-border bg-surface px-2 py-0.5 text-[10px] font-medium tabular-nums">
                <span
                  ref={(el) => ruler.attachLowerReadout(el)}
                  style={{ display: ruler.activeThumb ? "inline" : "none" }}
                >
                  {formatNumber(safeVal[0])}
                </span>
                <span
                  style={{ display: ruler.activeThumb ? "none" : "inline" }}
                >
                  <NumberRoll value={safeVal[0]} duration={380} />
                  {unit && (
                    <span className="ml-1 text-muted-foreground">{unit}</span>
                  )}
                </span>
              </div>
            </div>

            <div
              className="absolute -top-0.5 transition-[opacity,left] duration-200"
              style={{
                left: `${upperPercent}%`,
                transform: "translate(-50%, 0)",
              }}
            >
              <div className="inline-flex items-center rounded-full border border-border bg-surface px-2 py-0.5 text-[10px] font-medium tabular-nums">
                <span
                  ref={(el) => ruler.attachUpperReadout(el)}
                  style={{ display: ruler.activeThumb ? "inline" : "none" }}
                >
                  {formatNumber(safeVal[1])}
                </span>
                <span
                  style={{ display: ruler.activeThumb ? "none" : "inline" }}
                >
                  <NumberRoll value={safeVal[1]} duration={380} />
                  {unit && (
                    <span className="ml-1 text-muted-foreground">{unit}</span>
                  )}
                </span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* The Track & Graduated thin line Ruler */}
      <div className="relative py-2">
        {/* SVG Graduated Ruler Ticks */}
        <div className="relative h-6 w-full" aria-hidden="true">
          <svg
            className="size-full overflow-visible text-border"
            preserveAspectRatio="none"
          >
            {/* Base thin line Axis */}
            <line
              x1="0"
              y1="23.5"
              x2="100%"
              y2="23.5"
              stroke="currentColor"
              strokeWidth="1"
            />
            {ticks.map((t) => (
              <line
                key={t.key}
                x1={`${t.fraction * 100}%`}
                y1={t.isMajor ? 8 : 15}
                x2={`${t.fraction * 100}%`}
                y2={23}
                stroke="currentColor"
                strokeWidth="1"
                className={
                  t.isMajor ? "text-muted-foreground/60" : "text-border/80"
                }
              />
            ))}
          </svg>
        </div>

        {/* Track gesture container (allows drag anywhere on track) */}
        <div
          ref={(el) => ruler.attachTrack(el)}
          {...ruler.trackHandlers}
          className="relative h-6 w-full cursor-ew-resize touch-none select-none"
        >
          {/* Active Highlight Band */}
          <div
            ref={(el) => ruler.attachHighlight(el)}
            aria-hidden="true"
            className="pointer-events-none absolute top-0 h-full rounded border-y border-primary/40 bg-primary/10"
            style={{
              left: `${lowerPercent}%`,
              width: `${Math.max(0, upperPercent - lowerPercent)}%`,
            }}
          />

          {/* Lower Needle Thumb */}
          <button
            ref={(el) => ruler.attachLowerThumb(el)}
            {...ruler.lowerHandlers}
            type="button"
            role="slider"
            disabled={disabled}
            aria-label={`Minimum ${label ?? "value"}`}
            aria-valuemin={lower}
            aria-valuemax={safeVal[1] - minDistance}
            aria-valuenow={safeVal[0]}
            aria-valuetext={formatAria(safeVal[0])}
            aria-describedby={lowerHint}
            className={`absolute -top-1 z-10 flex h-8 w-6 cursor-ew-resize items-center justify-center rounded-md border border-border bg-background touch-none select-none disabled:cursor-default disabled:opacity-40 will-change-[left] before:absolute before:-inset-x-3 before:-inset-y-2 before:content-[''] ${INTERACTION_FOCUS}`}
            style={{
              left: `${lowerPercent}%`,
              transform: "translate(-50%, 0)",
            }}
          >
            {/* 1px Vertical Needle */}
            <span className="h-5 w-px bg-primary" />
          </button>

          {/* Upper Needle Thumb */}
          <button
            ref={(el) => ruler.attachUpperThumb(el)}
            {...ruler.upperHandlers}
            type="button"
            role="slider"
            disabled={disabled}
            aria-label={`Maximum ${label ?? "value"}`}
            aria-valuemin={safeVal[0] + minDistance}
            aria-valuemax={upper}
            aria-valuenow={safeVal[1]}
            aria-valuetext={formatAria(safeVal[1])}
            aria-describedby={upperHint}
            className={`absolute -top-1 z-10 flex h-8 w-6 cursor-ew-resize items-center justify-center rounded-md border border-border bg-background touch-none select-none disabled:cursor-default disabled:opacity-40 will-change-[left] before:absolute before:-inset-x-3 before:-inset-y-2 before:content-[''] ${INTERACTION_FOCUS}`}
            style={{
              left: `${upperPercent}%`,
              transform: "translate(-50%, 0)",
            }}
          >
            {/* 1px Vertical Needle */}
            <span className="h-5 w-px bg-primary" />
          </button>
        </div>

        {/* Lower / Upper Bound Labels */}
        <div
          aria-hidden="true"
          className="mt-2 flex justify-between text-[10px] font-mono tabular-nums text-muted-foreground/70"
        >
          <span>{formatNumber(lower)}</span>
          <span>{formatNumber(upper)}</span>
        </div>
      </div>

      <p id={lowerHint} className="sr-only">
        Adjust minimum. Left arrow decreases, right arrow increases. Shift
        increases step by 10. Home sets to minimum, End to maximum.
      </p>
      <p id={upperHint} className="sr-only">
        Adjust maximum. Left arrow decreases, right arrow increases. Shift
        increases step by 10. Home sets to minimum, End to maximum.
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";
import { EASE_SETTLE, rubberBand } from "./imported-ui-interaction-motion";

export function snapRulerValue(
  value: number,
  min: number,
  max: number,
  step: number,
) {
  if (!Number.isFinite(value) || value <= min) return min;
  if (value >= max) return max;
  const snapped = min + Math.round((value - min) / step) * step;
  return Number(Math.max(min, Math.min(max, snapped)).toFixed(6));
}

type Range = [number, number];

type RangeRulerOptions = {
  value: Range;
  min: number;
  max: number;
  step: number;
  minDistance?: number;
  disabled: boolean;
  reduced: boolean;
  onChange?: (value: Range) => void;
  onCommit?: (value: Range) => void;
  format: (value: number) => string;
  formatNumber: (value: number) => string;
};

/** High-performance gesture controller for a dual-needle graduated ruler. */
export function useRangeRuler(options: RangeRulerOptions) {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const lowerThumbRef = React.useRef<HTMLButtonElement>(null);
  const upperThumbRef = React.useRef<HTMLButtonElement>(null);
  const highlightRef = React.useRef<HTMLDivElement>(null);
  const lowerReadoutRef = React.useRef<HTMLSpanElement>(null);
  const upperReadoutRef = React.useRef<HTMLSpanElement>(null);
  const mergedReadoutRef = React.useRef<HTMLSpanElement>(null);

  const optionsRef = React.useRef(options);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
  });

  const [activeThumb, setActiveThumb] = React.useState<
    "lower" | "upper" | null
  >(null);
  const [isMerged, setIsMerged] = React.useState(false);

  // Active drag state kept strictly in refs to prevent layout thrash and React re-renders.
  const gesture = React.useRef<{
    id: number;
    thumb: "lower" | "upper";
    startVal: Range;
    currentVal: Range;
    trackLeft: number;
    trackWidth: number;
  } | null>(null);

  const getRatio = React.useCallback((val: number) => {
    const { min, max } = optionsRef.current;
    const span = Math.max(0.00001, max - min);
    return Math.max(0, Math.min(1, (val - min) / span));
  }, []);

  const paint = React.useCallback(
    (range: Range, animate: boolean) => {
      const o = optionsRef.current;
      const [lower, upper] = range;
      const lowerRatio = getRatio(lower);
      const upperRatio = getRatio(upper);

      const lowerPct = (lowerRatio * 100).toFixed(4);
      const upperPct = (upperRatio * 100).toFixed(4);
      const spanPct = Math.max(0, (upperRatio - lowerRatio) * 100).toFixed(4);

      const transition =
        animate && !o.reduced ? `left 360ms ${EASE_SETTLE}` : "none";
      const barTransition =
        animate && !o.reduced
          ? `left 360ms ${EASE_SETTLE}, width 360ms ${EASE_SETTLE}`
          : "none";

      if (lowerThumbRef.current) {
        lowerThumbRef.current.style.transition = transition;
        lowerThumbRef.current.style.left = `${lowerPct}%`;
        lowerThumbRef.current.setAttribute("aria-valuenow", String(lower));
        lowerThumbRef.current.setAttribute("aria-valuetext", o.format(lower));
      }

      if (upperThumbRef.current) {
        upperThumbRef.current.style.transition = transition;
        upperThumbRef.current.style.left = `${upperPct}%`;
        upperThumbRef.current.setAttribute("aria-valuenow", String(upper));
        upperThumbRef.current.setAttribute("aria-valuetext", o.format(upper));
      }

      if (highlightRef.current) {
        highlightRef.current.style.transition = barTransition;
        highlightRef.current.style.left = `${lowerPct}%`;
        highlightRef.current.style.width = `${spanPct}%`;
      }

      if (lowerReadoutRef.current)
        lowerReadoutRef.current.textContent = o.formatNumber(lower);
      if (upperReadoutRef.current)
        upperReadoutRef.current.textContent = o.formatNumber(upper);
      if (mergedReadoutRef.current) {
        mergedReadoutRef.current.textContent =
          lower === upper
            ? o.formatNumber(lower)
            : `${o.formatNumber(lower)} – ${o.formatNumber(upper)}`;
      }

      const track = trackRef.current;
      const trackWidth = track ? track.offsetWidth : 400;
      const pixelGap = (upperRatio - lowerRatio) * trackWidth;
      setIsMerged(pixelGap < 48);
    },
    [getRatio],
  );

  const commit = React.useCallback(
    (next: Range, animate = true) => {
      const o = optionsRef.current;
      const dist = o.minDistance ?? 0;
      let lower = snapRulerValue(next[0], o.min, o.max - dist, o.step);
      let upper = snapRulerValue(next[1], o.min + dist, o.max, o.step);

      if (lower > upper - dist) {
        if (next[0] > o.value[0]) upper = Math.min(o.max, lower + dist);
        else lower = Math.max(o.min, upper - dist);
      }

      const clean: Range = [lower, upper];
      paint(clean, animate);
      o.onChange?.(clean);
      o.onCommit?.(clean);
    },
    [paint],
  );

  const finish = React.useCallback(
    (cancelled: boolean) => {
      const g = gesture.current;
      if (!g) return;
      gesture.current = null;
      setActiveThumb(null);

      if (cancelled) {
        paint(g.startVal, true);
        optionsRef.current.onChange?.(g.startVal);
      } else {
        commit(g.currentVal, false);
      }
    },
    [commit, paint],
  );

  React.useLayoutEffect(() => {
    if (!gesture.current) paint(options.value, true);
  }, [options.value, options.min, options.max, options.reduced, paint]);

  React.useEffect(() => {
    const handleResize = () => {
      if (!gesture.current) paint(optionsRef.current.value, false);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [paint]);

  React.useEffect(() => {
    const interrupted = () => finish(true);
    const hidden = () => {
      if (document.hidden) interrupted();
    };
    window.addEventListener("blur", interrupted);
    document.addEventListener("visibilitychange", hidden);
    return () => {
      window.removeEventListener("blur", interrupted);
      document.removeEventListener("visibilitychange", hidden);
    };
  }, [finish]);

  React.useEffect(() => {
    if (options.disabled) finish(true);
  }, [options.disabled, finish]);

  const startDrag = React.useCallback(
    (thumb: "lower" | "upper", event: React.PointerEvent<HTMLElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      const track = trackRef.current;
      if (!track) return;

      const rect = track.getBoundingClientRect();
      event.currentTarget.setPointerCapture(event.pointerId);

      const targetEl =
        thumb === "lower" ? lowerThumbRef.current : upperThumbRef.current;
      targetEl?.focus({ preventScroll: true });

      gesture.current = {
        id: event.pointerId,
        thumb,
        startVal: [...optionsRef.current.value] as Range,
        currentVal: [...optionsRef.current.value] as Range,
        trackLeft: rect.left,
        trackWidth: Math.max(1, rect.width),
      };

      setActiveThumb(thumb);
      paint(optionsRef.current.value, false);
    },
    [paint],
  );

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      const g = gesture.current;
      const o = optionsRef.current;
      if (!g || g.id !== event.pointerId) return;

      const clientX = event.clientX;
      const rawFraction = (clientX - g.trackLeft) / g.trackWidth;
      let fraction = rawFraction;
      if (rawFraction < 0) {
        fraction =
          -rubberBand(-rawFraction * g.trackWidth, g.trackWidth, 0.4) /
          g.trackWidth;
      } else if (rawFraction > 1) {
        fraction =
          1 +
          rubberBand((rawFraction - 1) * g.trackWidth, g.trackWidth, 0.4) /
            g.trackWidth;
      }
      const targetVal = snapRulerValue(
        o.min + Math.max(0, Math.min(1, fraction)) * (o.max - o.min),
        o.min,
        o.max,
        o.step,
      );
      const dist = o.minDistance ?? 0;

      let [lower, upper] = g.currentVal;

      if (g.thumb === "lower") {
        lower = Math.min(o.max - dist, targetVal);
        // Repulsion: lower pushes upper forward
        if (lower > upper - dist) {
          upper = Math.min(o.max, lower + dist);
        }
      } else {
        upper = Math.max(o.min + dist, targetVal);
        // Repulsion: upper pushes lower backward
        if (upper < lower + dist) {
          lower = Math.max(o.min, upper - dist);
        }
      }

      if (lower === g.currentVal[0] && upper === g.currentVal[1]) return;

      g.currentVal = [lower, upper];
      paint([lower, upper], false);
      o.onChange?.([lower, upper]);
    },
    [paint],
  );

  const onTrackPointerDown = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      // If clicking directly on a thumb button, let the thumb handler handle it
      if ((event.target as HTMLElement).closest("button")) return;

      const track = trackRef.current;
      if (!track) return;
      const rect = track.getBoundingClientRect();
      const fraction = Math.max(
        0,
        Math.min(1, (event.clientX - rect.left) / Math.max(1, rect.width)),
      );
      const clickVal =
        optionsRef.current.min +
        fraction * (optionsRef.current.max - optionsRef.current.min);

      const [lower, upper] = optionsRef.current.value;
      const closer: "lower" | "upper" =
        Math.abs(clickVal - lower) <= Math.abs(clickVal - upper)
          ? "lower"
          : "upper";

      startDrag(closer, event);
      // Immediately process movement to click position
      const targetVal = snapRulerValue(
        clickVal,
        optionsRef.current.min,
        optionsRef.current.max,
        optionsRef.current.step,
      );
      const dist = optionsRef.current.minDistance ?? 0;
      let nextLower = lower;
      let nextUpper = upper;

      if (closer === "lower") {
        nextLower = Math.min(optionsRef.current.max - dist, targetVal);
        if (nextLower > nextUpper - dist)
          nextUpper = Math.min(optionsRef.current.max, nextLower + dist);
      } else {
        nextUpper = Math.max(optionsRef.current.min + dist, targetVal);
        if (nextUpper < nextLower + dist)
          nextLower = Math.max(optionsRef.current.min, nextUpper - dist);
      }

      if (gesture.current) {
        gesture.current.currentVal = [nextLower, nextUpper];
        paint([nextLower, nextUpper], false);
        optionsRef.current.onChange?.([nextLower, nextUpper]);
      }
    },
    [startDrag, paint],
  );

  const makeKeyHandler = React.useCallback(
    (thumb: "lower" | "upper") =>
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        if (event.key === "Escape") {
          event.preventDefault();
          finish(true);
          return;
        }

        const o = optionsRef.current;
        if (
          ![
            "ArrowLeft",
            "ArrowRight",
            "ArrowUp",
            "ArrowDown",
            "PageUp",
            "PageDown",
            "Home",
            "End",
          ].includes(event.key)
        )
          return;

        event.preventDefault();
        const isUp = ["ArrowRight", "ArrowUp", "PageUp"].includes(event.key);
        const mult = event.key.startsWith("Page") || event.shiftKey ? 10 : 1;
        const delta = o.step * mult * (isUp ? 1 : -1);
        const dist = o.minDistance ?? 0;

        let [lower, upper] = o.value;

        if (thumb === "lower") {
          if (event.key === "Home") lower = o.min;
          else if (event.key === "End") lower = upper - dist;
          else lower = Math.max(o.min, Math.min(o.max - dist, lower + delta));

          if (lower > upper - dist) upper = Math.min(o.max, lower + dist);
        } else {
          if (event.key === "Home") upper = lower + dist;
          else if (event.key === "End") upper = o.max;
          else upper = Math.max(o.min + dist, Math.min(o.max, upper + delta));

          if (upper < lower + dist) lower = Math.max(o.min, upper - dist);
        }

        commit([lower, upper]);
      },
    [commit, finish],
  );

  const attachTrack = React.useCallback((el: HTMLDivElement | null) => {
    trackRef.current = el;
  }, []);
  const attachLowerThumb = React.useCallback((el: HTMLButtonElement | null) => {
    lowerThumbRef.current = el;
  }, []);
  const attachUpperThumb = React.useCallback((el: HTMLButtonElement | null) => {
    upperThumbRef.current = el;
  }, []);
  const attachHighlight = React.useCallback((el: HTMLDivElement | null) => {
    highlightRef.current = el;
  }, []);
  const attachLowerReadout = React.useCallback((el: HTMLSpanElement | null) => {
    lowerReadoutRef.current = el;
  }, []);
  const attachUpperReadout = React.useCallback((el: HTMLSpanElement | null) => {
    upperReadoutRef.current = el;
  }, []);
  const attachMergedReadout = React.useCallback(
    (el: HTMLSpanElement | null) => {
      mergedReadoutRef.current = el;
    },
    [],
  );

  const onPointerUpTrack = React.useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancelTrack = React.useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onPointerDownLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => startDrag("lower", e),
    [startDrag],
  );
  const onPointerUpLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancelLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onLostPointerCaptureLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onBlur = React.useCallback(() => finish(true), [finish]);
  const onKeyDownLower = React.useMemo(
    () => makeKeyHandler("lower"),
    [makeKeyHandler],
  );

  const onPointerDownUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => startDrag("upper", e),
    [startDrag],
  );
  const onPointerUpUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancelUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onLostPointerCaptureUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onKeyDownUpper = React.useMemo(
    () => makeKeyHandler("upper"),
    [makeKeyHandler],
  );

  const trackHandlers = React.useMemo(
    () => ({
      onPointerDown: onTrackPointerDown,
      onPointerMove,
      onPointerUp: onPointerUpTrack,
      onPointerCancel: onPointerCancelTrack,
    }),
    [onTrackPointerDown, onPointerMove, onPointerUpTrack, onPointerCancelTrack],
  );

  const lowerHandlers = React.useMemo(
    () => ({
      onPointerDown: onPointerDownLower,
      onPointerMove,
      onPointerUp: onPointerUpLower,
      onPointerCancel: onPointerCancelLower,
      onLostPointerCapture: onLostPointerCaptureLower,
      onBlur,
      onKeyDown: onKeyDownLower,
    }),
    [
      onPointerDownLower,
      onPointerMove,
      onPointerUpLower,
      onPointerCancelLower,
      onLostPointerCaptureLower,
      onBlur,
      onKeyDownLower,
    ],
  );

  const upperHandlers = React.useMemo(
    () => ({
      onPointerDown: onPointerDownUpper,
      onPointerMove,
      onPointerUp: onPointerUpUpper,
      onPointerCancel: onPointerCancelUpper,
      onLostPointerCapture: onLostPointerCaptureUpper,
      onBlur,
      onKeyDown: onKeyDownUpper,
    }),
    [
      onPointerDownUpper,
      onPointerMove,
      onPointerUpUpper,
      onPointerCancelUpper,
      onLostPointerCaptureUpper,
      onBlur,
      onKeyDownUpper,
    ],
  );

  return {
    attachTrack,
    attachLowerThumb,
    attachUpperThumb,
    attachHighlight,
    attachLowerReadout,
    attachUpperReadout,
    attachMergedReadout,
    activeThumb,
    isMerged,
    commit,
    trackHandlers,
    lowerHandlers,
    upperHandlers,
  };
}

